export interface SelfShipDebug {
  probe: () => SelfShipProbeResult;
  /** Start one frame sample per rendered frame (WorldManager calls sampleFrame). */
  startRecording: () => void;
  /** Stop and return collected samples (also clears). */
  stopRecording: () => SelfShipFrameSample[];
  /** Called from WorldManager's frame, right after renderer.render. No-op when not recording. */
  sampleFrame: (sample: SelfShipFrameSample) => void;
  /** Record one ClientShipPredictor.reconcile result (the bridge). */
  recordReconcile: (mode: 'blend' | 'rewind' | 'snap', correctionDistance: number) => void;
  reconcile: ReconcileStats;
}
```

And `SelfShipProbeResult` gets `camera: { pos: Vec3 } | null` added.

Wait, the spec says: add `camera: { pos: Vec3 } | null` to `SelfShipProbeResult`. So probe returns the camera's world coordinates. The bind source in main.tsx needs to provide the camera: from `world.cameraSample().pos`. Update the bindSelfShipDebug source at main.tsx line 1803 to include `camera: world.cameraSample()`.

EMPTY becomes `{ classId: null, pos: null, rot: null, screen: null, camera: null }`.

The recorder logic lives inside the installSelfShipDebug closure:

```ts
export function installSelfShipDebug(): SelfShipDebug | null {
  if (!import.meta.env.DEV) return null;
  let frames: SelfShipFrameSample[] | null = null;
  const reconcile: ReconcileStats = { blend: 0, rewind: 0, snap: 0, lastCorrectionDistance: null };
  const state: SelfShipDebug = {
    probe: () => EMPTY,
    reconcile,
    startRecording: () => { if (!frames) frames = []; },
    stopRecording: () => { const out = frames ?? []; frames = null; return out; },
    sampleFrame: (s) => { if (frames) frames.push(s); },
    recordReconcile: (mode, correctionDistance) => {
      reconcile[mode] += 1;
      reconcile.lastCorrectionDistance = correctionDistance;
    },
  };
  window.__SELF_SHIP__ = state;
  return state;
}
```

Hmm — "zero cost when not recording": sampleFrame is called every frame; the guard is `if (!frames) return;`. Fine.

Should recordReconcile also be zero-cost when not in use? It's only called from main.tsx when selfShipDebug is non-null (dev). Fine.

